package app.relaydrop;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.IOException;

/** Native SAF controls; a remote webpage cannot request or read device storage paths. */
public final class StorageActivity extends SecureActivity {
  private TextView status;
  private Button export,restore;
  private ProgressDialog progress;
  private volatile boolean cancelled,destroyed,busy;
  private int dp(int value){return (int)(getResources().getDisplayMetrics().density*value+.5f);}
  private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(20,44,53));t.setPadding(0,dp(10),0,dp(10));return t;}
  private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
  @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.rgb(244,247,246));LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(24),dp(24),dp(24),dp(24));scroll.addView(box);box.setOnApplyWindowInsetsListener((v,insets)->{box.setPadding(dp(24),dp(24)+insets.getSystemWindowInsetTop(),dp(24),dp(24)+insets.getSystemWindowInsetBottom());return insets;});setContentView(scroll);box.addView(text("文件池备份与迁移",26));box.addView(text("本机文件池保存位置",15));TextView location=text(new java.io.File(getFilesDir(),"relaydrop").getAbsolutePath(),13);location.setTextIsSelectable(true);box.addView(location);box.addView(text("文件保存在应用私有目录。退出程序不会删除；卸载或清除应用数据会删除。使用下面的导出功能，把原件保存到你选择的普通文件夹。",14));export=button("备份到文件夹（可加密）",()->choose(81));box.addView(export);restore=button("从备份恢复 / 迁移到此设备",()->new AlertDialog.Builder(this).setTitle("恢复备份到当前文件池？").setMessage("将先完整校验所有原件，再一次性加入当前文件池。现有文件和设备身份保留。\n\n共享文件会向当前已配对设备共享；原定向文件恢复为仅本机管理员可见。回收站项目保持在回收站。原备份不会删除。\n\n迁移手机时，可先在旧设备导出，再在新设备选择这份备份恢复。设备信任需要重新配对。").setNegativeButton("取消",null).setPositiveButton("选择完整备份",(d,w)->choose(82)).show());box.addView(restore);status=text(RelayService.server==null?"请先返回首页创建本机中转站，再备份或恢复。":"本机中转站已就绪。备份与恢复期间会暂停文件池写入。",14);box.addView(status);box.addView(text("备份包含共享、定向、回收站原件及文字；不包含设备令牌或密钥。每份原件在导出后读回核验 SHA-256。校验清单用于发现损坏，不是备份来源的数字签名，请只恢复你信任的备份。",13));box.addView(button("返回首页",this::finish));}
  private void choose(int request){if(busy)return;if(RelayService.server==null){status.setText("请先返回首页创建本机中转站。");return;}try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(request==81)intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(intent,request);}catch(Exception error){status.setText("无法打开系统文件夹选择器。");}}
  @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request==81||request==82)&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri tree=data.getData();try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(tree,flags);if(request==81)exportChoice(tree);else restoreChoice(tree);}catch(Exception error){status.setText(UploadQueueService.message(error));}}}
  private void run(boolean backup,Uri tree,char[] password){if(AppLock.isLocked(this)){if(password!=null)java.util.Arrays.fill(password,'\0');return;}RelayHttpServer server=RelayService.server;if(server==null){if(password!=null)java.util.Arrays.fill(password,'\0');status.setText("本机中转站已停止，请重新开启。");return;}busy=true;cancelled=false;export.setEnabled(false);restore.setEnabled(false);progress=new ProgressDialog(this);progress.setTitle(backup?"备份文件池":"核验并恢复备份");progress.setMessage("正在准备…");progress.setCancelable(false);progress.setButton(DialogInterface.BUTTON_NEGATIVE,"取消",(d,w)->cancelled=true);progress.show();new Thread(()->{String message;try{PoolBackup.Progress observer=new PoolBackup.Progress(){public void update(String value){runOnUiThread(()->{if(progress!=null&&!destroyed)progress.setMessage(value);});}public void check()throws IOException{if(cancelled||destroyed||Thread.currentThread().isInterrupted())throw new IOException("已取消；已完成原件和原文件池均保留。不完整导出目录不会被当作有效备份。");}};if(backup){Uri output=PoolBackup.export(this,server,tree,password,observer);message="备份完成，所有原件和清单已读回校验。\n"+output;}else{org.json.JSONObject restored=PoolBackup.restore(this,server,tree,password,observer);message="恢复完成："+restored.optInt("files")+" 个文件、"+restored.optInt("notes")+" 条文字。\n共享资料目录："+restored.optString("folderName")+"\n定向资料仅本机管理员可见；原备份保留。";}}catch(Exception error){message=UploadQueueService.message(error);}finally{if(password!=null)java.util.Arrays.fill(password,'\0');}String finalMessage=message;runOnUiThread(()->{busy=false;if(progress!=null){progress.dismiss();progress=null;}if(!destroyed){export.setEnabled(true);restore.setEnabled(true);status.setText(finalMessage);}});},"relay-pool-backup").start();}
  private void exportChoice(Uri tree){new AlertDialog.Builder(this).setTitle("备份保护方式").setMessage("备份包含共享、定向和回收站文件及文字。加密会同时隐藏原文件名、目录和内容；密码不会保存，遗忘后无法恢复。").setNegativeButton("取消",null).setPositiveButton("加密备份（推荐）",(d,w)->password(true,tree)).setNeutralButton("明文备份",(d,w)->new AlertDialog.Builder(this).setTitle("确认导出明文备份？").setMessage("能读取此目录的人可以查看备份中的全部共享、定向和回收站内容。校验清单不能提供保密性。").setNegativeButton("取消",null).setPositiveButton("确认明文导出",(dialog,which)->run(true,tree,null)).show()).show();}
  private void restoreChoice(Uri tree){status.setText("正在检查备份格式…");new Thread(()->{try{boolean encrypted=PoolBackup.encrypted(this,tree);runOnUiThread(()->{if(isDestroyed()||AppLock.isLocked(this))return;if(encrypted)password(false,tree);else new AlertDialog.Builder(this).setTitle("恢复明文备份？").setMessage("此目录没有加密备份头。仅当你确认它原本是明文备份且信任来源时恢复；文件校验不能证明备份来源。").setNegativeButton("取消",null).setPositiveButton("确认明文恢复",(d,w)->run(false,tree,null)).show();});}catch(Exception e){runOnUiThread(()->status.setText(UploadQueueService.message(e)));}},"relay-backup-inspect").start();}
  private void password(boolean backup,Uri tree){LinearLayout inputs=new LinearLayout(this);inputs.setOrientation(1);inputs.setPadding(dp(20),dp(8),dp(20),0);EditText first=new EditText(this);first.setSingleLine();first.setHint(backup?"设置备份密码":"备份密码");first.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);inputs.addView(first);EditText second=new EditText(this);second.setSingleLine();second.setHint("再次输入密码");second.setInputType(first.getInputType());if(backup)inputs.addView(second);TextView note=text("密码按原样使用，至少 8 个 UTF-8 字节。密码不保存在应用中。",13);inputs.addView(note);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(backup?"加密备份密码":"解密并恢复").setView(inputs).setNegativeButton("取消",null).setPositiveButton(backup?"开始加密备份":"验证并恢复",null).create();dialog.setOnDismissListener(d->{first.setText("");second.setText("");});dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(AppLock.isLocked(this)){dialog.dismiss();return;}String value=first.getText().toString();int bytes=value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(bytes<8||bytes>1024){first.setError("密码需为 8–1024 个 UTF-8 字节");return;}if(backup&&!value.equals(second.getText().toString())){second.setError("两次输入不一致");return;}char[] chars=value.toCharArray();dialog.dismiss();run(backup,tree,chars);}));dialog.show();dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}
  @Override public void onBackPressed(){if(busy){new AlertDialog.Builder(this).setTitle("取消存储任务？").setMessage("正在提交的恢复会先完成提交；其余步骤可取消。原文件池和原备份会保留。").setNegativeButton("继续任务",null).setPositiveButton("取消任务",(d,w)->cancelled=true).show();}else super.onBackPressed();}
  @Override protected void onDestroy(){destroyed=true;cancelled=true;if(progress!=null){progress.dismiss();progress=null;}super.onDestroy();}
}
